using CRM.Application.ReportingInsights;using Microsoft.AspNetCore.Mvc.Testing;using Microsoft.Extensions.DependencyInjection;using Xunit;namespace CRM.UnitTests;public sealed class Sprint29InsightHardeningTests{[Fact]public async Task FlagsAndMetrics_AreSafe(){using var f=new WebApplicationFactory<Program>();var svc=f.Services.GetRequiredService<IReportingInsightReadService>();var x=await svc.GetByKeyAsync("accounts-contacts");Assert.NotNull(x);Assert.All(x!.Metrics,m=>Assert.True(m.Value>=0));Assert.Equal("FoundationMock",x.SourceMode);Assert.False(x.ProductiveRuntimeEnabled);Assert.False(x.PortalRuntimeEnabled);Assert.False(x.CommonDbRuntimeEnabled);}}